#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basic() {
        assert_eq!(min_cover_window("XADOBECODEBANC", "ABC"), "BANC");
    }

    #[test]
    fn impossible() {
        assert_eq!(min_cover_window("a", "aa"), "");
        assert_eq!(min_cover_window("abc", "z"), "");
    }

    #[test]
    fn whole_string() {
        assert_eq!(min_cover_window("abc", "cba"), "abc");
    }

    #[test]
    fn multiplicity() {
        assert_eq!(min_cover_window("baxab", "aab"), "baxa");
        assert_eq!(min_cover_window("abcab", "aab"), "abca");
    }

    #[test]
    fn earliest_tie() {
        assert_eq!(min_cover_window("abxba", "ab"), "ab");
    }

    #[test]
    fn large() {
        let s = format!("{}ab{}", "x".repeat(20000), "y".repeat(20000));
        assert_eq!(min_cover_window(&s, "ba"), "ab");
    }
}
